import{_ as r,a0 as p,w as e,s as l,ao as d,I as o,x as s,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"pidstat - 监控并统计Linux进程的数据 | LCTT x X-CMD","titleTemplate":false,"description":"pidstat - 监控并统计Linux进程的数据 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"pidstat - 监控并统计Linux进程的数据 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"pidstat - 监控并统计Linux进程的数据 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141017 pidstat - Monitor and Find Statistics for Linux Procesess","title":"pidstat - 监控并统计Linux进程的数据","tag":"201411","desc":""},"relativePath":"201411/20141017 pidstat - Monitor and Find Statistics for Linux Procesess.md","filePath":"[post].md"}'),u={name:"201411/20141017 pidstat - Monitor and Find Statistics for Linux Procesess.md"};function g(m,t,x,c,f,h){const i=p("Link");return e(),l("div",null,[t[13]||(t[13]=d(`<h1 id="pidstat-监控并统计linux进程的数据" tabindex="-1">pidstat - 监控并统计Linux进程的数据 <a class="header-anchor" href="#pidstat-监控并统计linux进程的数据" aria-label="Permalink to “pidstat - 监控并统计Linux进程的数据”">​</a></h1><p><strong>pidstat</strong>命令用来监控被Linux内核管理的独立任务(进程)。它输出每个受内核管理的任务的相关信息。pidstat命令也可以用来监控特定进程的子进程。间隔参数用于指定每次报告间的时间间隔。它的值为0(或者没有参数)说明进程的统计数据的时间是从系统启动开始计算的。</p><h3 id="如何安装pidstat" tabindex="-1">如何安装pidstat <a class="header-anchor" href="#如何安装pidstat" aria-label="Permalink to “如何安装pidstat”">​</a></h3><p>pidstat 是sysstat软件套件的一部分，sysstat包含很多监控linux系统状态的工具，它能够从大多数linux发行版的软件源中获得。</p><p>在Debian/Ubuntu系统中可以使用下面的命令来安装</p><pre><code># apt-get install sysstat
</code></pre><p>CentOS/Fedora/RHEL版本的linux中则使用下面的命令：</p><pre><code># yum install sysstat
</code></pre><h3 id="使用pidstat" tabindex="-1">使用pidstat <a class="header-anchor" href="#使用pidstat" aria-label="Permalink to “使用pidstat”">​</a></h3><p>使用pidstat不加任何参数等价于加上-p参数，但是只有正在活动的任务会被显示出来。</p><pre><code># pidstat
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/09/pidstat.jpg" alt="pidstat"></p><p>在结果中你能看到如下内容：</p><ul><li><strong>PID</strong> - 被监控的任务的进程号</li><li><strong>%usr</strong> - 当在用户层执行(应用程序)时这个任务的cpu使用率，和 nice 优先级无关。注意这个字段计算的cpu时间不包括在虚拟处理器中花去的时间。</li><li><strong>%system</strong> - 这个任务在系统层使用时的cpu使用率。</li><li><strong>%guest</strong> - 任务花费在虚拟机上的cpu使用率（运行在虚拟处理器）。</li><li><strong>%CPU</strong> - 任务总的cpu使用率。在SMP环境(多处理器)中，如果在命令行中输入-I参数的话，cpu使用率会除以你的cpu数量。</li><li><strong>CPU</strong> - 正在运行这个任务的处理器编号。</li><li><strong>Command</strong> - 这个任务的命令名称。</li></ul><h3 id="i-o-统计数据" tabindex="-1">I/O 统计数据 <a class="header-anchor" href="#i-o-统计数据" aria-label="Permalink to “I/O 统计数据”">​</a></h3><p>通过使用-d参数来得到I/O的统计数据。比如：</p><pre><code># pidstat -d -p 8472
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/09/pidstat-io.jpg" alt="pidstat io"></p><p>IO 输出会显示一些内的条目：</p><ul><li><strong>kB_rd/s</strong> - 任务从硬盘上的读取速度（kb）</li><li><strong>kB_wr/s</strong> - 任务向硬盘中的写入速度（kb）</li><li><strong>kB_ccwr/s</strong> - 任务写入磁盘被取消的速率（kb）</li></ul><h3 id="页面失败和内存使用" tabindex="-1">页面失败和内存使用 <a class="header-anchor" href="#页面失败和内存使用" aria-label="Permalink to “页面失败和内存使用”">​</a></h3><p>使用-r标记你能够得到内存使用情况的数据。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/09/pidstat-pfmem.jpg" alt="pidstat pf mem"></p><p>重要的条目：</p><ul><li><strong>minflt/s</strong> - 从内存中加载数据时每秒出现的小的错误的数目，这些不要求从磁盘载入内存页面。</li><li><strong>majflt/s</strong> - 从内存中加载数据时每秒出现的较大错误的数目，这些要求从磁盘载入内存页面。</li><li><strong>VSZ</strong> - 虚拟容量：整个进程的虚拟内存使用（kb）</li><li><strong>RSS</strong> - 长期内存使用：任务的不可交换物理内存的使用量（kb）</li></ul><h3 id="举例" tabindex="-1">举例 <a class="header-anchor" href="#举例" aria-label="Permalink to “举例”">​</a></h3><p><strong>1.</strong> 你可以通过使用下面的命令来监测内存使用</p><pre><code># pidstat -r 2 5
</code></pre><p>这会给你5份关于page faults的统计数据结果，间隔2秒。这将会更容易的定位出现问题的进程。</p><p><strong>2.</strong> 显示所有mysql服务器的子进程</p><pre><code># pidstat -T CHILD -C mysql
</code></pre><p><strong>3.</strong> 将所有的统计数据结合到一个便于阅读的单一报告中：</p><pre><code># pidstat -urd -h
</code></pre><hr>`,34)),o("p",null,[t[1]||(t[1]=s("via: ",-1)),a(i,{href:"http://linoxide.com/linux-command/linux-pidstat-monitor-statistics-procesess/"},{default:n(()=>[...t[0]||(t[0]=[s("http://linoxide.com/linux-command/linux-pidstat-monitor-statistics-procesess/",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=s("作者：",-1)),a(i,{href:"http://linoxide.com/author/adriand/"},{default:n(()=>[...t[2]||(t[2]=[s("Adrian Dinu",-1)])]),_:1}),t[6]||(t[6]=s(" 译者：",-1)),a(i,{href:"https://github.com/johnhoow"},{default:n(()=>[...t[3]||(t[3]=[s("John",-1)])]),_:1}),t[7]||(t[7]=s(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...t[4]||(t[4]=[s("wxy",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=s("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[s("LCTT",-1)])]),_:1}),t[11]||(t[11]=s(" 原创翻译，",-1)),a(i,{href:"http://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[s("Linux中国",-1)])]),_:1}),t[12]||(t[12]=s(" 荣誉推出",-1))])])}const C=r(u,[["render",g]]);export{T as __pageData,C as default};
